import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry conv2d_nchw_fp32(
    .param .u64 in_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 out_ptr,
    .param .u32 N,
    .param .u32 C_in,
    .param .u32 H,
    .param .u32 W,
    .param .u32 C_out,
    .param .u32 K,
    .param .u32 stride,
    .param .u32 pad,
    .param .u32 H_out,
    .param .u32 W_out,
    .param .u32 total_elems
)
{
    .reg .pred %p<10>;
    .reg .b32 %r<80>;
    .reg .b64 %rd<40>;
    .reg .f32 %f<8>;

    // Load params
    ld.param.u64 %rd0, [in_ptr];
    ld.param.u64 %rd1, [w_ptr];
    ld.param.u64 %rd2, [b_ptr];
    ld.param.u64 %rd3, [out_ptr];

    ld.param.u32 %r10, [N];
    ld.param.u32 %r11, [C_in];
    ld.param.u32 %r12, [H];
    ld.param.u32 %r13, [W];
    ld.param.u32 %r14, [C_out];
    ld.param.u32 %r15, [K];
    ld.param.u32 %r16, [stride];
    ld.param.u32 %r17, [pad];
    ld.param.u32 %r18, [H_out];
    ld.param.u32 %r19, [W_out];
    ld.param.u32 %r20, [total_elems];

    // Compute global linear thread id (1D grid)
    mov.u32 %r0, %tid.x;
    mov.u32 %r1, %ctaid.x;
    mov.u32 %r2, %ntid.x;
    mad.lo.s32 %r3, %r1, %r2, %r0; // r3 = tid

    // Bounds check
    setp.ge.u32 %p0, %r3, %r20;
    @%p0 bra RET;

    // Decompose linear index into (n, oc, oh, ow)
    // ow = tid % W_out; tmp = tid / W_out
    rem.u32 %r30, %r3, %r19;  // ow
    div.u32 %r31, %r3, %r19;  // tmp1

    // oh = tmp1 % H_out; tmp2 = tmp1 / H_out
    rem.u32 %r32, %r31, %r18; // oh
    div.u32 %r33, %r31, %r18; // tmp2

    // oc = tmp2 % C_out; n = tmp2 / C_out
    rem.u32 %r34, %r33, %r14; // oc
    div.u32 %r35, %r33, %r14; // n

    // ih0 = oh*stride - pad ; iw0 = ow*stride - pad
    mul.lo.s32 %r36, %r32, %r16; // oh*stride
    sub.s32   %r36, %r36, %r17;  // ih0
    mul.lo.s32 %r37, %r30, %r16; // ow*stride
    sub.s32   %r37, %r37, %r17;  // iw0

    // Precompute sizes
    mul.lo.u32 %r40, %r12, %r13;     // HW
    mul.lo.u32 %r41, %r11, %r40;     // CHW
    mul.lo.u32 %r42, %r15, %r15;     // KK
    mul.lo.u32 %r43, %r11, %r42;     // C_in * K*K

    // base offsets
    mul.lo.u32 %r44, %r35, %r41;     // baseN for input (n * C*H*W)
    mul.lo.u32 %r45, %r34, %r43;     // baseOc for weights (oc * C_in*K*K)

    // Load bias[oc] into accumulator
    mul.wide.u32 %rd10, %r34, 4;
    add.s64 %rd11, %rd2, %rd10;
    ld.global.f32 %f0, [%rd11];      // acc = bias
    mov.f32 %f1, %f0;                // accumulator in %f1

    // ic loop
    mov.u32 %r50, 0;                 // ic = 0
IC_LOOP:
    setp.ge.u32 %p1, %r50, %r11;
    @%p1 bra IC_DONE;

    // kh loop
    mov.u32 %r51, 0;                 // kh = 0
KH_LOOP:
    setp.ge.u32 %p2, %r51, %r15;
    @%p2 bra KH_DONE;

    // ih = ih0 + kh
    add.s32 %r52, %r36, %r51;

    // if (ih < 0 || ih >= H) continue KH
    setp.lt.s32 %p3, %r52, 0;
    setp.ge.s32 %p4, %r52, %r12;
    or.pred %p8, %p3, %p4;
    @%p8 bra KH_CONT;

    // kw loop
    mov.u32 %r53, 0;                 // kw = 0
KW_LOOP:
    setp.ge.u32 %p5, %r53, %r15;
    @%p5 bra KW_DONE;

    // iw = iw0 + kw
    add.s32 %r54, %r37, %r53;

    // if (iw < 0 || iw >= W) continue KW
    setp.lt.s32 %p6, %r54, 0;
    setp.ge.s32 %p7, %r54, %r13;
    or.pred %p9, %p6, %p7;
    @%p9 bra KW_CONT;

    // input index: baseN + ic*HW + ih*W + iw
    mul.lo.u32 %r60, %r50, %r40;     // ic*HW
    mul.lo.u32 %r61, %r52, %r13;     // ih*W
    add.u32 %r62, %r44, %r60;
    add.u32 %r62, %r62, %r61;
    add.u32 %r62, %r62, %r54;

    // weight index: baseOc + ic*KK + kh*K + kw
    mul.lo.u32 %r63, %r50, %r42;     // ic*KK
    mul.lo.u32 %r64, %r51, %r15;     // kh*K
    add.u32 %r65, %r45, %r63;
    add.u32 %r65, %r65, %r64;
    add.u32 %r65, %r65, %r53;

    // load input and weight
    mul.wide.u32 %rd20, %r62, 4;
    add.s64 %rd21, %rd0, %rd20;
    ld.global.f32 %f2, [%rd21];

    mul.wide.u32 %rd22, %r65, 4;
    add.s64 %rd23, %rd1, %rd22;
    ld.global.f32 %f3, [%rd23];

    // acc += in * w
    fma.rn.f32 %f1, %f2, %f3, %f1;

KW_CONT:
    add.u32 %r53, %r53, 1;
    bra KW_LOOP;

KW_DONE:
KH_CONT:
    add.u32 %r51, %r51, 1;
    bra KH_LOOP;

KH_DONE:
    add.u32 %r50, %r50, 1;
    bra IC_LOOP;

IC_DONE:
    // Write output at ((n*C_out + oc)*H_out + oh)*W_out + ow
    mul.lo.u32 %r70, %r18, %r19;     // H_out * W_out
    mul.lo.u32 %r71, %r14, %r70;     // C_out * H_out * W_out
    mul.lo.u32 %r72, %r35, %r71;     // n * Cout*Ho*Wo
    mul.lo.u32 %r73, %r34, %r70;     // oc * Ho*Wo
    mul.lo.u32 %r74, %r32, %r19;     // oh * W_out

    add.u32 %r75, %r72, %r73;
    add.u32 %r75, %r75, %r74;
    add.u32 %r75, %r75, %r30;        // + ow

    mul.wide.u32 %rd30, %r75, 4;
    add.s64 %rd31, %rd3, %rd30;
    st.global.f32 [%rd31], %f1;

RET:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv2d_nchw_fp32")

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)

    def forward(self, x: torch.Tensor):
        assert x.is_cuda, "Input must be a CUDA tensor"
        assert x.dtype == torch.float32, "Only float32 is supported"
        weight = self.conv1.weight
        bias = self.conv1.bias
        assert weight.is_cuda and bias is not None and bias.is_cuda, "Parameters must be CUDA tensors"
        assert x.is_contiguous() and weight.is_contiguous() and bias.is_contiguous(), "Tensors must be contiguous"

        N, C_in, H, W = x.shape
        K = self.conv1.kernel_size[0]
        stride = self.conv1.stride[0]
        pad = self.conv1.padding[0]
        C_out = self.conv1.out_channels

        H_out = (H + 2 * pad - K) // stride + 1
        W_out = (W + 2 * pad - K) // stride + 1

        out = torch.empty((N, C_out, H_out, W_out), device=x.device, dtype=x.dtype)

        total = N * C_out * H_out * W_out
        block_x = 256
        grid_x = (total + block_x - 1) // block_x

        module = _get_ptx_module()
        module.launch(
            "conv2d_nchw_fp32",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[
                x, weight, bias, out,
                i32(N), i32(C_in), i32(H), i32(W),
                i32(C_out), i32(K), i32(stride), i32(pad),
                i32(H_out), i32(W_out), i32(total)
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

