    add.s32 %r52, %r36, %r51;

    // if (ih < 0 || ih >= H) continue KH
    setp.lt.s32 %p3, %r52, 0;
    setp.ge.s32 %p4, %r52, %r12;
    or.pred %p8, %p3, %p4;
    @%p8 bra KH_CONT;

    // kw loop
    mov.u32 %r53, 0;                 // kw = 0
KW_LOOP:
    setp.ge.u32 %p5, %r53, %r15;
    @%p5 bra KW_DONE;

    // iw = iw0 + kw
    add.s32 %r54, %r37, %r53;

    // if (iw < 0 || iw >= W) continue KW
    setp.lt.s32 %p6, %r54, 0;
    setp.ge.s32 %p7, %r54, %r13;
    or.pred %p9, %p6, %p7;
    @%p9 bra KW_CONT;

    // input index: baseN + ic*HW + ih*W + iw
    mul.lo.u32 %r60, %r50, %r40;     // ic*HW
    mul.lo.u32 %r61, %r52, %r13;     // ih*W
    add.u32 %r62, %r44, %r60;
    add.u32 %r62, %r62, %r61;
    add.u32 %r62, %r62, %r54;

    // weight index: baseOc + ic*KK + kh*K + kw
    mul.lo.u32 %r63, %r50, %r42;     // ic*KK
    mul.lo.u32 %r64, %r51, %r15;     // kh*K
    add.u32 %r65, %r45, %r63;
    add.u32 %r65, %r65, %r64;
    add.u32 %r65, %r65, %r53;

    // load input and weight
    mul.wide.u32 %rd20, %r62, 4;
    add.s64 %rd21, %rd0, %rd20;
    ld.global.f32 %f2, [%rd21];

    mul.wide.u32 %rd22, %r65, 4;
    add.s64 %rd23, %rd1, %rd22;
    ld.global.f32 %f3, [%rd23];

    // acc += in * w
    fma.rn.f32 %f1, %f2, %f3, %f1;

KW_CONT:
    add.u32 %r53, %r53, 1;
    bra KW_LOOP;

KW_DONE:
KH_CONT:
    add.u32 %r51, %r51, 1;
    bra KH_LOOP;

KH_DONE:
    add.u32 %r50, %r50, 1;
    bra IC_LOOP;

IC_DONE:
    // Write output at ((n*C_out + oc)*H_out + oh)*W_out + ow
    mul.lo.u32 %r70, %r18, %r19;     // H_out * W_out
    mul.lo.u32 %r71, %r14, %r70;     // C_out * H_out * W_out
    mul.lo.u32 %r72, %r35, %r71;     // n * Cout*Ho*Wo
    mul.lo.u32 %r73, %r34, %r70;     // oc * Ho*Wo
    mul.lo.u32 %r74, %r32, %r19;     // oh * W_out

    add.u32 %r75, %r72, %r73;
    add.u32 %r75, %r75, %r74;
    add.u32 %r75, %r75, %r30;        // + ow

    mul.wide.u32 %rd30, %r75, 4;
    add.s64 %rd31, %rd3, %rd30;
    st.global.f32 [%rd31], %f1;

RET:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv2d_nchw_fp32")

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)

    def forward(self, x: torch.Tensor):
        assert x.is_cuda, "Input must be a CUDA tensor"
        assert x.dtype == torch.float32, "Only float32 is supported"
        weight = self.conv1.weight
        bias = self.conv1.bias
        assert weight.is_cuda and bias is not None and bias.is_cuda, "Parameters must be CUDA tensors"
        assert x.is_contiguous() and weight.is_contiguous() and bias.is_contiguous(), "Tensors must be contiguous"

        N, C_in, H, W = x.shape
        K = self.conv1.kernel_size[0]
        stride = self.conv1.stride[0]
        pad = self.conv1.padding[0]
        C_out = self.conv1.out_channels

        H_out = (H + 2 * pad - K) // stride + 1
        W_out = (W + 2 * pad - K) // stride + 1

        out = torch.empty((N, C_out, H_out, W_out), device=x.device, dtype=x.dtype)

        total = N * C_out * H_out * W_out
        block_x = 256
        grid_x = (total + block_x - 1) // block_x

        module = _get_ptx_module()
        module.launch(
            "conv2d_nchw_fp32",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[
                x, weight, bias, out,
                i32(N), i32(C_in), i32(H), i32(W),
                i32(C_out), i32(K), i32(stride), i32(pad),
                i32(H_out), i32(W_out), i32(total)
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out
